-- SIEGE WORLDS WEAPON PARITY (2026-Aug-22)
--
-- DreadRoot already had every Siege Worlds weapon, at matching tiers, with
-- matching item_numbers — but items.properties was EMPTY ({}) on all of them.
-- The weapons could be owned and equipped and had no stats behind them at all:
-- no damage, no clip size, no reload time, no fire rate, no sounds.
--
-- Source: the Unity client's own item configs, Assets/Resources/config/*.asset
-- (191 gun entries; 25 weapons x their WeaponLevels). Siege Worlds levels are
-- 0-based and DreadRoot tiers are 1-based, so level N maps to tier N+1.
--
-- Written under properties->'sw' so the provenance is obvious and nothing
-- DreadRoot later stores in properties can collide with it.
--
-- 186 of 190 rows match. The 4 that do not are tier-8 variants of Double
-- Barrel Shotgun, Flamethrower, AK74 and Bonnie's Rifle, which Siege Worlds
-- has and DreadRoot does not.
with sw(dr_name, sw) as (values
  ($dr$Plasma Pistol$dr$, $j${"maxDamage":50,"clipSize":17,"reloadTime":1.15,"shootCooldown":0.3,"timeBetweenShots":0,"bulletsPerTap":0,"effectiveRange":75,"isAutomatic":false,"isBurstFire":false,"isShotgun":false,"isSniper":false,"isRocketLauncher":false,"fireSound":"plasma_pistol_shot","emptySound":"pistol_empty","reloadSound":"pistol_reload"}$j$::jsonb),
  ($dr$Double Barrel Shotgun$dr$, $j${"maxDamage":50,"clipSize":2,"reloadTime":1.5,"shootCooldown":0.7,"timeBetweenShots":0.3,"bulletsPerTap":6,"effectiveRange":45,"isAutomatic":false,"isBurstFire":false,"isShotgun":true,"isSniper":false,"isRocketLauncher":false,"fireSound":"DB_Shot","emptySound":"empty_shot","reloadSound":"DB_reload"}$j$::jsonb),
